import { Component } from '@angular/core';

@Component({
  selector: 'app-navbar',
  templateUrl: './navbar.component.html',
  styleUrls: ['./navbar.component.css']
})
export class NavbarComponent {
  isMenuOpen = false;

  toggleMenu() {
    this.isMenuOpen = !this.isMenuOpen;
  }
}
<header class="nav-root">
  <div class="nav-inner">
    <a routerLink="/" class="nav-logo">
      <span class="nav-logo-mark">λ</span>
      <span class="nav-logo-text">
        <span class="nav-logo-title">Angular Learning Portal</span>
        <span class="nav-logo-subtitle">From zero to confident</span>
      </span>
    </a>

    <nav class="nav-links" [class.nav-links--open]="isMenuOpen">
      <a routerLink="/" routerLinkActive="nav-link--active" [routerLinkActiveOptions]="{ exact: true }">Dashboard</a>
      <a routerLink="/courses" routerLinkActive="nav-link--active">Courses</a>
      <a routerLink="/about" routerLinkActive="nav-link--active">About</a>
    </nav>

    <button class="nav-menu-button" (click)="toggleMenu()">
      <span *ngIf="!isMenuOpen">☰</span>
      <span *ngIf="isMenuOpen">✕</span>
    </button>
  </div>
</header>
